from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
SAFE=['Tiyakin ang qualification,training,duty scope,at aprubadong procedure sa equipment operation,measurement,machining,o setting change.']
m.lesson(81,'Maintenance effects,terms,at record comparison','Suriin ang maintenance ayon sa nilalaman at kondisyon ng epekto.',[
('Konkretong layunin','Layunin ang safety,less defects,longer life,less downtime loss/cost. Pagsamahin ang periodic service,monitoring,repair;hindi laging hanggang failure dahil mura ang part.'),('Huwag pangalan lamang','Makitid ang pagkakaiba ng maintenance terms sa textbook,ngunit maaaring kasama sa “hoshu” ang inspection/prevention sa ibang field/standard. Huwag pangalan lamang ang safety o duty;tingnan ang actual work,stop conditions,return criteria.'),('Conditions ng effect comparison','Kailangan ang operating hours/production,repair content,downtime,bukod sa failure count. Mas maikling replacement interval ay preventive ngunit maaaring mas cost/waste. Predictive ay kailangan din ng monitoring equipment at control values.')],['Advance inspection/service upang mabawasan ang failure.','Maintenance ayon sa state signs.','Production at ibang loss mula equipment stop.','Itinakdang value para sa condition evaluation.'],ACT+'Ihambing ang monthly2failures/100hours at3/300hours sa rate. Isulat ang maintenance,cost,safety,downtime checks.',['Huwag laktawan ang isolation/authority kahit daily check ang pangalan.'],'Suriin ang maintenance ayon sa nilalaman at kondisyon ng epekto.')
m.lesson(82,'Packaging signs,stacking,at PPM','Ilapat ang signs sa handling at itugma ang denominator sa logistics evaluation.',[
('Protection at distribution','Iangkop sa shock,vibration,humidity,storage time,shape. Iba ang cushion at fixation. Pumili ng paper,cardboard,wood,metal,resin ayon sa layunin;hindi outer appearance lamang ang protection.'),('Labels sa handling','Ihiwalay ang fragile,keep dry,handle with care,no stacking,stack limit. Sa textbook,nang bilang ng load na mailalagay sa ibabaw ng nasa ibaba ang n;sa aktuwal,itugma ang label at specification. Huwag basta baguhin upang mag-overload.'),('Per million','PPM ang ratio bawat million.2sa10000shipments ay2/10000×1000000=200PPM. Huwag fixed pass value mula industry/warehouse type lamang;itugma ang customer target,scope,period,counting. Kasama ang deadline,product,quantity,address.')],['Pagpapahayag ng ratio bawat million.','Materyal na nagpapahina sa impact.','Materyal na pumipigil sa paglipat ng produkto.','Tagubilin sa limitasyon ng stack layers.'],ACT+'Kunin angPPM ng3sa25000. Ihiwalay sa drawings ang no stacking at hanggang2sa ibabaw. Gumawa ng evaluation table kasama ang wrong address.',['Sundin ang handling at allowable conditions sa heavy packages.'],'Ilapat ang signs sa handling at itugma ang denominator sa logistics evaluation.')
m.lesson(83,'Mold,release,at FRP sa injection molding','Ihiwalay ang flow path,mold holding,release at tiyakin sa specification ang composites.',[
('Resin path','Mula hopper,heated cylinder/screw,sa sprue,runner,gate,at product cavity. Clamp ang humahawak laban sa injection pressure;kontrolin ang temperature,pressure,amount,speed,cooling ayon sa takda.'),('Release at storage','Draft angle tumutulong sa release,ejector pin sa paglabas. Huwag ipaghalo ang gate/sprue;tingnan ang design ng product/mold. Kontrolin ang rust,humidity,dirt sa storage;huwag basta i-share sa ibang produkto.'),('Resin at fibers','Iba ang properties/processing ng thermoplastic,thermoset,biodegradable. Nag-iiba ang mechanical/electrical sa glass/carbon fiber type,direction,quantity. Tingnan ang strength,lightness,chemical resistance,flammability,surface damage,waste/recycling sa specs;hindi lahat FRP pareho.')],['Paghihiwalay/pagkuha ng molded product mula mold.','Slope upang madaling alisin sa mold.','Pasukan ng resin sa product cavity.','Pin na nagtutulak palabas ng molded product.'],ACT+'Iguhit ang sprue,runner,gate,draft,ejector at ipaliwanag kung bakit hindi basta carbon-fiber part sa insulating part.',['Huwag kamay sa mold;isolation at approved procedure sa clog/mold change.'],'Ihiwalay ang flow path,mold holding,release at tiyakin sa specification ang composites.')
m.lesson(84,'Board structure,exposure,development,etching','Ihiwalay ang structure,formation,removal targets at protektahan ang needed copper sa film.',[
('Layers at materials','Single/double/multilayer ang conductor-layer structure;rigid/flex/composite ang form. Iba ang base at heat dissipation sa paper-phenolic,glass-epoxy,ceramic,metal-base. Ibang stage ang assembled circuit board.'),('Iwan ang kailangang conductor','Sa subtractive,gumawa ng protective pattern at etch ang unwanted copper. Sa ibang method,selective plating ang conductor. Iba ayon sa resist ang mask,exposure,development;huwag parehong light/dark conditions sa lahat.'),('Film at copper:magkaibang removal','Sa negative-type conceptual example,naiiwan ang exposure-hardened film,development ang unexposed film,etch ang exposed copper,saka strip ang natirang protective film. Hindi isinasama ang needed protected copper sa removal. Kontrolin ang temperature,concentration,cleaning,surface treatment,outline,inspection.')],['Controlled light exposure sa photosensitive material.','Pag-alis ng takdang photo-film matapos exposure upang lumikha ng pattern.','Pag-alis ng natitirang film at iba pa.','Board na pinagsamang maraming conductor layers.'],ACT+'Kulayan nang hiwalay ang base,needed/unwanted copper,protective film. Ipaliwanag ang targets ng development,copper etch,film strip at bakit hindi actual chemical recipe ang konsepto.',['Huwag magpatakbo ng UV,chemical,plating,waste mula textbook explanation lamang.'],'Ihiwalay ang structure,formation,removal targets at protektahan ang needed copper sa film.')
m.lesson(85,'Pag-uugnay ng konkretong panganib at signs sa trabaho','Iugnay sa tiyak na kilos ang safety devices,transport,solvents,at disaster signs.',[
('Safety devices at ibang tao','Kung fixed ang isang two-hand button,maaaring pumasok ang libreng kamay sa danger part. Ihiwalay ang guard removal,sensor disable,at bukas na likod na nalalapitan ng iba. Tingnan ang emergency-stop location bago magsimula;hindi dahilan iyon upang walang guard.'),('Visibility at daanan','Blocked view sa transport,open ditch,at cable/protrusion sa hagdan ay collision/fall factors. Kung natatakpan ng karga ang paa,huwag magpatuloy nang hindi kita;tingnan ang aprubadong transport. Sa solvent,hiwalay na hazards ang stopped ventilation,open container,wet floor.'),('Target ng sign','Prohibitions din ang no running,no phone,no electronics. Iba ang tsunami hazard area at refuge;landslide/cliff warnings ay sakuna rin. Huwag ipalit ang flame,corrosion,health,aquatic-environment,irritant;itugma ang product/SDS. Ang wide-area evacuation site ay malaking espasyo laban sa major fire at iba pa.')],['Operation na nangangailangan ng parehong kamay sa controls.'],ACT+'Sa fixed start button at blocked-view transport,gumawa ng apat na kolum:source,human action,possible injury,measures needing approval.',SAFE,'Sa pag-uugnay ng konkretong panganib/signs,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(86,'Pagbasa ng paper,line,text drafting instructions','Ihiwalay ang paper size,line type/width,text,at dimension instructions.',[
('Papel at border','A0:841×1189mm,A1:594×841mm,A2:420×594mm,A3:297×420mm,A4:210×297mm. Textbook border examples:A4～A2margin10mm,A1pataas20mm. Tingnan ang adopted form/binding margin sa drawing;huwag paper edge ang dimension reference.'),('Width at line type','Basic thin/thick ratio1:2;examples0.18/0.35,0.25/0.5,0.35/0.7,0.5/1.0mm. Pantayin ang parehong function. Single-dot chain sa reference/pitch,double-dot sa imagined movement,wavy/zigzag break sa omitted boundary. Iba ang cutting location sa diagonal hatching ng cut surface.'),('Readable entries','Text heights:2.5,3.5,5,7,10mm. Iwasan ang crossing dimensions/duplicate sizes upang mabasa ang final dimension. Iba ang arc length,chord,central angle. Textbook M:milling,L:lathe sa process note;basahin kasama angRa. Tingnan ang version/legend.')],['Linyang nagpapakita ng adjacent parts o motion range at iba pa.'],ACT+'Kalkulahin ang size ng kalahatingA2;ipaliwanag ang outline,imaginary,cut location,hatching. Bakit i-hold kung magkaiba ang duplicate dimensions?',SAFE,'Sa paper,line,text instructions,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(87,'Pagtiyak ng electrical symbols sa terminals at operation','Itugma ang symbols sa terminals,operation,at return conditions.',[
('Hugis at function','Itugma ang resistor/variable/capacitor/coil shapes at roles. Sa diode,LED,photodiode,tingnan angA,K,at light arrows. B,C,Eang pnp;huwag basta ipagpalit. Hindi photograph ng real shape/pin order ang symbol.'),('Operation at return','Ihiwalay ang automatic return ng pushbutton/alarm switch sa maintained/manual release ng emergency stop. May make,break,positive-opening limit switches;iba ang proximity at mechanical position detection. Itugma ang symbols/contact behavior kahit magkahawig ang pangalan.'),('Device symbol at reference','Textbook R:relay,MC:contactor,THR:thermal,BS:pushbutton,L:lamp. Iba ang ibang circuit;kaya legend ang una. Ihiwalay ang ammeterA,fuse,wiring breaker,indicator. Sundan left-to-right o top-to-bottom ang operation. Itugma ang coil/contacts sa number/reference.')],['Pagbalik sa dating state kapag binitiwan ang control.'],ACT+'Sa independent symbol diagram,ituro ang resistor,capacitor,coil,diode,LED,photodiode,a/b contacts,ammeter,fuse at ipaliwanag. Huwag kopyahin ang originalPDFfigure;itugma ang legend.',SAFE,'Sa electrical symbols,tingnan ang terminals,operation,structure,gamit,applicability,bukod sa pangalan.')
m.lesson(88,'Conditional material comparison at insulation classification','Ipaliwanag nang may kondisyon ang conductor,magnetic,insulating values.',[
('Conductor comparison','Sa textbook,aluminum conductivity ay humigit-kumulang60%ng soft copper,density ay1/3. Iba ang lightness at conductivity benefits. Sa20°C,resistivities:soft copper1/58,hard copper1/55,aluminum1/35 saΩ·mm²/mkasama ang area. Panatilihin ang material/temperature assumptions;hindi lahat alloy.'),('Magnetic at resistance materials','Nichrome ay heating resistance material;may temperature-stable resistance material din. Hindi low resistance ang laging mabuti. Core:permeability,saturation flux density;permanent magnet:remanence,coercivity. Huwag iisang “magnetic strength” ang ferrite/alnico;gamit ang requirements.'),('Insulation structure at temperature','PETthermoplastic na may Mylar name example;phenolic/epoxy thermoset. Kraft/pressboard insulating paper;mica/ceramic inorganic. Sa textbook temperature-rise example,ibinabawas ang ambient40°Csa maximum,ngunit hindi lahat product limit ang formula. Tiyakin din ang temperature/reference water saSGcomparison.')],['Katangiang kaugnay ng hirap baguhin ang magnetized state.'],ACT+'Ihambing ang resistivity ng same-length/area soft copper/aluminum,hiwalay sa weight benefit. Ihiwalay ang classF155°Cminus40°Ctextbook calculation sa tunay na product ambient check.',SAFE,'Sa conditional material values/insulation classes,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(89,'Pagtutugma ng fastening parts at tool shapes','Itugma sa drawing ang screw head,nut,washer,at tool.',[
('Tool sa nut','Box driver o nut driver para sa maliit na nuts. Spanner/ring sa tamang across-flats;adjustable wrench ay walang gap. Tingnan sa movable-jaw structure/manual ang load direction;iwasang pilitin sa direksiyong bumubuka ang jaw.'),('Head at washer configuration','May pan,countersunk,raised-countersunk machine screws;iba ang tool fit ng slot/cross. Washer-assembled ay SEMS din. Flat washer nagpapalawak ng contact load at iba pa;tingnan ang position sa metal/nonmetal. Hindi guarantee ang spring washer laban sa lahat ng loosening.'),('Actual at drawing','May example na hold screw head sa device at higpitan ang nut,o screw sa tapped hole. Iba ang configuration sa material/receiving thread. May resin/rubber washers at locking nuts;huwag ipalit dahil kamukha;tingnan ang part,orientation,count,torque.')],['Screw na may naka-assemble na washer.'],ACT+'Tatlong kombinasyon ng tool para sa hex-socket bolt,hex nut,cross screw. Isulat ang check bago tightening kapag kulang ang specified flat washer sa nonmetal plate.',SAFE,'Sa fastening/tool shapes,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
